#!/bin/bash
# Generated by AI with GitHub Copilot.

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd) || exit 1
MSXGL_PATH=${MSXGL_PATH:-$(dirname "$SCRIPT_DIR")}
WIZARD_SCRIPT="$MSXGL_PATH/engine/script/wizard/wizard.js"

if [ ! -f "$WIZARD_SCRIPT" ]; then
	echo "MSXgl project wizard was not found: $WIZARD_SCRIPT" >&2
	exit 1
fi

if [ -x "$MSXGL_PATH/tools/build/Node/node" ]; then
	NODE="$MSXGL_PATH/tools/build/Node/node"
elif command -v node >/dev/null 2>&1; then
	NODE=$(command -v node)
else
	echo "Node.js was not found. Install Node.js or restore the bundled runtime." >&2
	exit 1
fi

exec "$NODE" "$WIZARD_SCRIPT" "$@"
